style.css:
[role="tooltip"],
[role="region"],
[aria-modal="true"],
[aria-haspopup="true"],
div[style*="z-index"],
div[class*="modal"],
div[class*="popup"],
div[class*="dialog"],
div[class*="overlay"],
div[class*="layer"] {
  background-color: black !important;
  background-image: none !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  color: #d0e7ff !important;
}


[role="dialog"] *,
[role="tooltip"] *,
div[class*="popup"] *,
div[class*="overlay"] * {
  color: #d0e7ff !important;
  background-color: transparent !important;
}
